package pe.edu.upeu.pago.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;
import pe.edu.upeu.pago.entity.*;import pe.edu.upeu.pago.client.MercadoPagoClient;import pe.edu.upeu.pago.repository.*;import java.time.*;import java.math.BigDecimal;
@Service @RequiredArgsConstructor
public class ConciliacionPagoService {
 private final OrdenCompraRepository ordenes;private final OrdenCertificadoRepository certificados;private final MovimientoSaldoRepository movimientos;private final MercadoPagoClient mp;private final LiquidacionService liquidaciones;private final BloqueoSaldoService bloqueo;private final Clock clock;private final ReembolsoRepository reembolsos;private final pe.edu.upeu.pago.client.InscripcionClient inscripciones;
 @Value("${kido.pagos.dias-retencion:7}") private long dias;
 @Transactional public void compra(Long id){bloqueo.bloquear(ordenes.docenteDe(id).orElseThrow());var o=ordenes.bloquear(id).orElseThrow();if(o.getMercadoPagoPaymentId()==null||o.getMercadoPagoPaymentId().startsWith("SIM-"))return;var p=mp.obtenerPago(o.getMercadoPagoPaymentId());if(!String.valueOf(id).equals(p.externalReference()))throw new IllegalArgumentException("Referencia de pago no coincide");p.validarImporte(o.getMontoTotal());copiar(o,p);var m=movimientos.findByOrdenIdAndTipo(id,MovimientoSaldo.TipoMovimiento.VENTA).orElseThrow();aplicar(m,p,o.getFechaAprobacion());if("approved".equals(p.status())&&reembolsos.findByOrdenId(id).filter(r->r.getEstado()==Reembolso.EstadoReembolso.SOLICITADO).isPresent()){m.setEstado(MovimientoSaldo.EstadoMovimiento.BLOQUEADO);movimientos.save(m);}if("refunded".equals(p.status())||"charged_back".equals(p.status())){o.setEstado("refunded".equals(p.status())?OrdenCompra.EstadoOrden.REEMBOLSADA:OrdenCompra.EstadoOrden.CONTRACARGO);o.setRequiereRevocacion(true);}ordenes.save(o);}
 @Transactional public void certificado(Long id){bloqueo.bloquear(certificados.docenteDe(id).orElseThrow());var o=certificados.bloquear(id).orElseThrow();if(o.getMercadoPagoPaymentId()==null||o.getMercadoPagoPaymentId().startsWith("SIM-"))return;var p=mp.obtenerPago(o.getMercadoPagoPaymentId());if(!("CERT-"+id).equals(p.externalReference()))throw new IllegalArgumentException("Referencia de certificado no coincide");p.validarImporte(o.getMontoTotal());copiar(o,p);var m=movimientos.findByOrdenCertificadoId(id).orElseThrow();aplicar(m,p,o.getFechaAprobacion());if("refunded".equals(p.status())||"charged_back".equals(p.status()))o.setEstado("refunded".equals(p.status())?OrdenCertificado.EstadoOrden.REEMBOLSADA:OrdenCertificado.EstadoOrden.CONTRACARGO);certificados.save(o);}
 private void aplicar(MovimientoSaldo m,MercadoPagoClient.PagoExterno p,LocalDateTime aprobacion){
  boolean revertido="refunded".equals(p.status())||"charged_back".equals(p.status());
  boolean disputa=!"approved".equals(p.status())||(p.reembolsado()!=null&&p.reembolsado().signum()>0);
  if(revertido||disputa||"blocked".equals(p.fondosEstado())||(m.getEstado()==MovimientoSaldo.EstadoMovimiento.DISPONIBLE&&(!"released".equals(p.fondosEstado())||p.costoProcesamiento()==null||p.netoRecibido()==null)))liquidaciones.bloquearPendientes(m.getDocenteId(),"Pago retenido, devuelto o con contracargo; requiere nueva liquidación");
  m.setConciliado(p.costoProcesamiento()!=null&&p.netoRecibido()!=null);
  if(revertido)m.setEstado(MovimientoSaldo.EstadoMovimiento.REVERTIDO);
  else if(disputa||"blocked".equals(p.fondosEstado()))m.setEstado(MovimientoSaldo.EstadoMovimiento.BLOQUEADO);
  else {LocalDateTime disponible=aprobacion.plusDays(dias);LocalDateTime liberacion=liberacion(p.fechaLiberacion());if(liberacion==null&&"released".equals(p.fondosEstado()))liberacion=m.getEstado()==MovimientoSaldo.EstadoMovimiento.DISPONIBLE?m.getFechaDisponible():LocalDateTime.now(clock);if(liberacion!=null&&liberacion.isAfter(disponible))disponible=liberacion;m.setFechaDisponible(disponible);m.setEstado(m.isConciliado()&&"released".equals(p.fondosEstado())&&!disponible.isAfter(LocalDateTime.now(clock))?MovimientoSaldo.EstadoMovimiento.DISPONIBLE:MovimientoSaldo.EstadoMovimiento.PENDIENTE);}
  movimientos.save(m);
 }
 @Transactional public void revocarAcceso(Long id){var o=ordenes.bloquear(id).orElseThrow();if(!o.isRequiereRevocacion())return;inscripciones.revocar(o.getEstudianteId(),o.getCursoId());o.setRequiereRevocacion(false);ordenes.save(o);}
 public static LocalDateTime liberacion(String valor){if(valor==null)return null;return OffsetDateTime.parse(valor).atZoneSameInstant(ZoneId.of("America/Lima")).toLocalDateTime();}
 public static void copiar(OrdenCompra o,MercadoPagoClient.PagoExterno p){o.setCostoProcesamiento(p.costoProcesamiento());o.setNetoRecibido(p.netoRecibido());o.setFondosEstado(p.fondosEstado());o.setFechaLiberacion(liberacion(p.fechaLiberacion()));o.setFechaConciliacion(LocalDateTime.now(ZoneId.of("America/Lima")));}
 public static void copiar(OrdenCertificado o,MercadoPagoClient.PagoExterno p){o.setCostoProcesamiento(p.costoProcesamiento());o.setNetoRecibido(p.netoRecibido());o.setFondosEstado(p.fondosEstado());o.setFechaLiberacion(liberacion(p.fechaLiberacion()));o.setFechaConciliacion(LocalDateTime.now(ZoneId.of("America/Lima")));}
}
